<?php
declare(strict_types=1);require_once __DIR__.'/../includes/bootstrap.php';$pageTitle='Memories & Photos';$selected=filter_input(INPUT_GET,'folder',FILTER_VALIDATE_INT);
$folders=$pdo->query('SELECT f.id,f.name,f.description,COUNT(p.id) photo_count FROM photo_folders f LEFT JOIN photos p ON p.folder_id=f.id GROUP BY f.id ORDER BY f.name')->fetchAll();$valid=array_map(static fn($x)=>(int)$x['id'],$folders);if($selected&&!in_array($selected,$valid,true))$selected=null;
if($selected){$q=$pdo->prepare('SELECT p.*,f.name folder_name FROM photos p JOIN photo_folders f ON f.id=p.folder_id WHERE p.folder_id=? ORDER BY p.uploaded_at DESC');$q->execute([$selected]);}else{$q=$pdo->query('SELECT p.*,f.name folder_name FROM photos p JOIN photo_folders f ON f.id=p.folder_id ORDER BY p.uploaded_at DESC LIMIT 80');}$photos=$q->fetchAll();$selectedName='All memories';foreach($folders as $f)if((int)$f['id']===(int)$selected)$selectedName=$f['name'];include __DIR__.'/../includes/header.php';?>
