<?php if(!$photos):?><div class="empty-state"><div class="empty-icon">▧</div><h3>This folder is waiting for a memory.</h3><p>Upload JPG, PNG or WebP images and organise them into folders.</p><button class="btn btn-outline" type="button" data-open-modal="uploadModal">Upload your first photo</button></div><?php else:?><div class="photo-grid"><?php foreach($photos as $ph):?><article class="photo-card"><button type="button" class="photo-image-button" data-photo-src="../uploads/photos/<?=e($ph['file_name'])?>" data-photo-caption="<?=e($ph['caption']?:$ph['original_name'])?>"><img src="../uploads/photos/<?=e($ph['file_name'])?>" alt="<?=e($ph['caption']?:$ph['original_name'])?>" loading="lazy"></button><div class="photo-meta"><strong><?=e($ph['caption']?:$ph['original_name'])?></strong><small><?=e($ph['folder_name'])?></small><div class="photo-actions"><button class="mini-action" type="button" data-edit-photo='<?=e(json_encode($ph,JSON_HEX_APOS|JSON_HEX_QUOT|JSON_HEX_TAG|JSON_HEX_AMP))?>' aria-label="Edit photo">✎</button><form class="inline-form" method="post" action="../actions/photo-remove.php" data-confirm="Remove this photo permanently?"><?=csrf_field()?><input type="hidden" name="id" value="<?=(int)$ph['id']?>"><button class="mini-action danger-action" type="submit" aria-label="Remove photo">×</button></form></div></div></article><?php endforeach;?></div><?php endif;?></section></div>
